// 课文 (texts) data API — separate from the flashcard data module.
// Text data lives in src/data/texts/{series}-{unit}.json (generated by
// scripts/convert_texts.py) and is lazy-loaded, one chunk per unit.
// The glob pattern requires a dash so texts/meta.json is excluded.

import { COURSE_REGISTRY } from "./courses.js";
import meta from "./texts/meta.json"; // { "hsk-1": { lessonCount, textCount }, ... }

const loaders = import.meta.glob("./texts/*-*.json");

function key(seriesId, unitId) {
  return `${seriesId}-${unitId}`;
}

// Series/units that actually have 课文 (currently 旧版 hsk 1-3, 新版 newhsk3 1-3).
// Reuses the flashcard series metadata (name, colors) for a consistent look.
export const textsRegistry = COURSE_REGISTRY.map((series) => ({
  ...series,
  units: series.units
    .map((unit) => {
      const m = meta[key(series.id, unit.id)];
      return m ? { ...unit, lessonCount: m.lessonCount, textCount: m.textCount } : null;
    })
    .filter(Boolean),
})).filter((s) => s.units.length);

export function hasTexts(seriesId, unitId) {
  return !!meta[key(seriesId, unitId)];
}

// Whether a specific lesson has a 课文 (text lessons are numbered to match the
// flashcard lessons, so a lesson within lessonCount has texts).
export function hasTextLesson(seriesId, unitId, lessonNum) {
  const m = meta[key(seriesId, unitId)];
  return !!m && Number(lessonNum) >= 1 && Number(lessonNum) <= m.lessonCount;
}

const _cache = new Map();
export function loadTextUnit(seriesId, unitId) {
  const k = key(seriesId, unitId);
  if (_cache.has(k)) return _cache.get(k);
  const loader = loaders[`./texts/${k}.json`];
  const p = loader ? loader().then((m) => m.default) : Promise.resolve(null);
  _cache.set(k, p);
  return p;
}

export const getTextUnit = loadTextUnit;

export async function getTextLesson(seriesId, unitId, lessonNum) {
  const ds = await loadTextUnit(seriesId, unitId);
  if (!ds) return null;
  return ds.lessons.find((l) => l.num === Number(lessonNum)) || null;
}
